int main(int argc,char**argv){if(argc!=5)return 2;AVFormatContext*i=0,*o=0;avformat_open_input(&i,argv[1],0,0);avformat_find_stream_info(i,0);int vi=av_find_best_stream(i,AVMEDIA_TYPE_VIDEO,-1,-1,0,0),target=atoi(argv[3]),idx=0;avformat_alloc_output_context2(&o,0,0,argv[2]);AVStream*s=avformat_new_stream(o,0);avcodec_parameters_copy(s->codecpar,i->streams[vi]->codecpar);s->codecpar->codec_tag=0;s->time_base=i->streams[vi]->time_base;o->avoid_negative_ts=AVFMT_AVOID_NEG_TS_DISABLED;avio_open(&o->pb,argv[2],AVIO_FLAG_WRITE);if(avformat_write_header(o,0)<0)return 3;AVPacket*p=av_packet_alloc();while(av_read_frame(i,p)>=0){if(p->stream_index==vi){int current=idx++;if(current!=target||atoi(argv[4])){if(current==target){av_packet_make_writable(p);if(p->size<10)return 4;p->data[7]^=0x20;}av_packet_rescale_ts(p,i->streams[vi]->time_base,s->time_base);p->stream_index=0;p->pos=-1;if(av_interleaved_write_frame(o,p)<0)return 5;}}av_packet_unref(p);}av_write_trailer(o);av_packet_free(&p);avformat_close_input(&i);avio_closep(&o->pb);avformat_free_context(o);return 0;}
